// V14 I18N — translation scaffold
// ══════════════════════════════════════════════════════════════════════════
// Phase 1 (current): scaffold the t() helper, the strings map, and the locale
// picker. Only the most-visible UI strings are externalized to demonstrate the
// pattern. Phase 2 (future): externalize all hardcoded English strings to
// STRINGS[locale] entries; localize. Phase 3: bring in translators for nl, de,
// fr, es. The locale presets are already in user settings.
//
// Usage: t('inbox.empty', 'Your inbox is clear.')
//   - Looks up STRINGS[locale][key]; falls back to the provided default
//   - Default acts as both English text and a sentinel: never throws if a key
//     is missing in a translation file
//
// Locale resolution order: explicit user setting → browser language → 'en'.

// ──────────────────────────────────────────────────────────────────────────
// Translation catalogue. en-GB is the source language; every other locale
// inherits from en-GB for missing keys (handled by t()'s fallback chain).
//
// Key naming convention: `area.subarea.thing`
//   nav.*       — primary navigation labels
//   btn.*       — generic button labels (Save, Cancel, etc.)
//   form.*      — form field labels
//   stage.*     — report workflow stage labels
//   sev.*       — defect severity levels
//   status.*    — defect status values
//   sync.*      — sync state indicators
//   auth.*      — auth screen copy
//   toast.*     — toast notification messages
//   page.*      — page titles, intros, empty states
//   settings.*  — settings panel labels
//   confirm.*   — confirmation prompts
//   placeholder.* — input placeholders
//
// Translators: en-GB has every key. Add a key in your locale only if the
// translation differs. Missing keys fall back through 'en' → fallback arg.
// ──────────────────────────────────────────────────────────────────────────
