// Supported locales surfaced in the picker (en-GB is the source-of-truth).
// Add new locales to STRINGS above AND this list to make them user-selectable.
var VX_LOCALES = [
  { code: 'en',    label: 'English',        flag: '🌐' },
  { code: 'nl-NL', label: 'Nederlands',    flag: '🇳🇱' },
  { code: 'de-DE', label: 'Deutsch',       flag: '🇩🇪' },
  { code: 'fr-FR', label: 'Français',      flag: '🇫🇷' },
  { code: 'es-ES', label: 'Español',       flag: '🇪🇸' },
];

function vxLocale() {
  try {
    const s = JSON.parse(localStorage.getItem('vx-settings-v1') || '{}');
    if(s.locale && STRINGS[s.locale]) return s.locale;
  } catch(e){}
  const nav = (navigator.language || 'en').replace('_', '-');
  if(STRINGS[nav]) return nav;
  // Try base language match (e.g. 'en' or 'en-AU' → 'en')
  const base = nav.split('-')[0];
  const found = Object.keys(STRINGS).find(k => k.startsWith(base + '-'));
  return found || 'en';
}

// Persist a new locale and re-render the visible page.
function vxSetLocale(code) {
  if(!STRINGS[code]) return false;
  try {
    // vx-settings-v1 is an IDB-backed entity key — read/write via ls()/lss() so
    // the locale change reaches IndexedDB + the sync queue (not LS-only).
    const s = (typeof ls === 'function') ? ls('vx-settings-v1', {}) : JSON.parse(localStorage.getItem('vx-settings-v1') || '{}');
    s.locale = code;
    if(typeof lss === 'function') lss('vx-settings-v1', s); else localStorage.setItem('vx-settings-v1', JSON.stringify(s));
    // Tell other parts of the app
    document.documentElement.lang = code;
    window.dispatchEvent(new CustomEvent('vx:locale-change', { detail: { locale: code } }));
    // Re-render visible UI
    if(typeof i18nApply === 'function') i18nApply();
    if(typeof updateDeployModePill === 'function') updateDeployModePill();
    const active = document.querySelector('.page.active');
    if(active?.id) {
      const pageId = active.id.replace('page-', '');
      if(pageId === 'reports'  && typeof rptRender === 'function')        rptRender();
      else if(pageId === 'defects' && typeof defRender === 'function')    defRender();
      else if(pageId === 'inbox'   && typeof inboxRender === 'function')  inboxRender();
      else if(pageId === 'overview' && typeof ovRefreshDashboard === 'function') ovRefreshDashboard();
    }
    return true;
  } catch(e) { console.warn('vxSetLocale failed', e); return false; }
}

// Translation lookup. Falls back: locale → en-GB → fallback arg → key itself.
function t(key, fallback) {
  const loc = vxLocale();
  const lookup = STRINGS[loc]?.[key];
  if(lookup) return lookup;
  // Fall back through 'en' first
  const enLookup = STRINGS['en']?.[key];
  if(enLookup) return enLookup;
  // If the caller explicitly passed a fallback — even an empty string —
  // honour it. The earlier `|| fallback || key` pattern was a footgun:
  // it treated '' as missing and returned the key itself, which broke
  // any caller using empty-string-as-sentinel (notably the help manual
  // body lookup, which expects '' to mean "no translation, use the
  // canonical HELP_CONTENT body instead"). Without this fix, the entire
  // user manual rendered the literal string `help.body.<chapter>` in
  // place of every chapter's content.
  if(fallback !== undefined) return fallback;
  return key;
}

// Format helper: t('msg.found', '{n} found', {n: 5}) → "5 found"
function tf(key, fallback, params) {
  let s = t(key, fallback);
  if(params) for(const k in params) s = s.replace('{' + k + '}', params[k]);
  return s;
}

// Apply translations to DOM elements with data-i18n="key" attribute.
// Used at boot and whenever the locale changes.
// V34: also handles `data-i18n-html` (allows HTML in the translation),
// `data-i18n-placeholder` / `data-i18n-title` (sets those attributes from
// a key separate from the textContent translation).
function i18nApply(root) {
  const scope = root || document;
  // 1) Standard data-i18n — sets textContent (or placeholder/title via data-i18n-target)
  scope.querySelectorAll('[data-i18n]').forEach(elNode => {
    const key = elNode.getAttribute('data-i18n');
    if(!key) return;
    const txt = t(key);
    if(elNode.dataset.i18nTarget === 'placeholder') elNode.placeholder = txt;
    else if(elNode.dataset.i18nTarget === 'title')  elNode.title = txt;
    else if(elNode.dataset.i18nTarget === 'aria-label') elNode.setAttribute('aria-label', txt);
    else if(elNode.dataset.i18nHtml === '1') elNode.innerHTML = txt;
    else elNode.textContent = txt;
  });
  // 2) data-i18n-placeholder — sets `placeholder` from a separate key,
  //    leaving the element's existing textContent / data-i18n logic intact.
  scope.querySelectorAll('[data-i18n-placeholder]').forEach(elNode => {
    const key = elNode.getAttribute('data-i18n-placeholder');
    if(key) elNode.placeholder = t(key);
  });
  // 3) data-i18n-title — same pattern for the title attribute (tooltips)
  scope.querySelectorAll('[data-i18n-title]').forEach(elNode => {
    const key = elNode.getAttribute('data-i18n-title');
    if(key) elNode.title = t(key);
  });
  // 4) data-i18n-aria-label — same pattern for ARIA labels
  scope.querySelectorAll('[data-i18n-aria-label]').forEach(elNode => {
    const key = elNode.getAttribute('data-i18n-aria-label');
    if(key) elNode.setAttribute('aria-label', t(key));
  });
  // 5) Refresh collapsed-sidebar hover tooltips from the (now-localized) labels.
  if(typeof vxSetSnavTooltips === 'function') vxSetSnavTooltips();
}
// Run after DOM is ready
if(document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => { i18nApply(); vxSyncCopyrightYear(); });
} else {
  i18nApply();
  vxSyncCopyrightYear();
}

// V17: display helpers for data-identifier labels.
// Stages, severities, and statuses are stored as English strings in records
// (they're the canonical identifier). These helpers translate them for
// display while keeping the underlying data unchanged.
function tStage(s) {
  const map = {
    'Draft':     'stage.draft',
    'Submitted': 'stage.submitted',
    'Reviewed':  'stage.reviewed',
    'Approved':  'stage.approved',
    'Archived':  'stage.archived',
  };
  return map[s] ? t(map[s], s) : s;
}
function tSeverity(s) {
  const map = {
    'Critical': 'sev.critical',
    'High':     'sev.high',
    'Medium':   'sev.medium',
    'Low':      'sev.low',
  };
  return map[s] ? t(map[s], s) : s;
}
function tStatus(s) {
  const map = {
    'Open':         'status.open',
    'In Progress':  'status.in_progress',
    'Repaired':     'status.repaired',
    'Verified':     'status.verified',
    'Closed':       'status.closed',
  };
  return map[s] ? t(map[s], s) : s;
}

// V17: locale picker grid renderer. Called by the Appearance settings page
// when it opens, and again whenever the locale changes (to update the
// "selected" highlight).
function renderLocalePicker() {
  const grid = document.getElementById('ap-locale-grid');
  if(!grid) return;
  const current = vxLocale();
  grid.innerHTML = VX_LOCALES.map(loc => {
    const isCurrent = loc.code === current;
    return `<button type="button"
      class="theme-card ${isCurrent ? 'active' : ''}"
      data-action="_wPickLocale" data-args="'${loc.code}'"
      style="display:flex;flex-direction:column;align-items:center;gap:4px;padding:14px 10px;min-height:auto"
      aria-pressed="${isCurrent}">
      <span style="font-size:24px;line-height:1" aria-hidden="true">${loc.flag}</span>
      <span style="font-size:13px;font-weight:500;color:var(--t1)">${loc.label}</span>
      <span style="font-family:var(--mono);font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:.05em">${loc.code}</span>
    </button>`;
  }).join('');
}

// Wrapper invoked by the picker buttons
function _wPickLocale(code) {
  if(vxSetLocale(code)) {
    toast(tf('toast.updated', '{lang} selected', { lang: VX_LOCALES.find(l=>l.code===code)?.label || code }), 'success');
    renderLocalePicker();
  }
}

// Refresh the picker whenever appearance is opened
window.addEventListener('vx:locale-change', () => renderLocalePicker());
